fn ndarray_stub_module() -> GeneratedCrateModule {
    GeneratedCrateModule {
        name: "ndarray",
        rust: r#"
use std::ops::{Index, IndexMut};

#[derive(Clone, PartialEq, Default)]
pub struct Array2<T> {
    rows: usize,
    cols: usize,
    values: Vec<T>,
}

impl<T: Clone> Array2<T> {
    pub fn from_elem(shape: (usize, usize), value: T) -> Self {
        Self {
            rows: shape.0,
            cols: shape.1,
            values: vec![value; shape.0 * shape.1],
        }
    }

    pub fn from_rows(rows: &[&[T]]) -> Self {
        let row_count = rows.len();
        let col_count = rows.first().map_or(0, |row| row.len());
        Self {
            rows: row_count,
            cols: col_count,
            values: rows.iter().flat_map(|row| row.iter().cloned()).collect(),
        }
    }

    pub fn fill(&mut self, value: T) {
        self.values.fill(value);
    }
}

pub fn arr2<T: Clone, const R: usize, const C: usize>(rows: &[[T; C]; R]) -> Array2<T> {
    Array2 {
        rows: R,
        cols: C,
        values: rows.iter().flat_map(|row| row.iter().cloned()).collect(),
    }
}

impl<T> Array2<T> {
    pub fn nrows(&self) -> usize {
        self.rows
    }

    pub fn ncols(&self) -> usize {
        self.cols
    }

    pub fn row(&self, row: usize) -> Vec<T>
    where
        T: Clone,
    {
        let start = row * self.cols;
        self.values[start..start + self.cols].to_vec()
    }

    pub fn row_mut(&mut self, row: usize) -> RowMut<'_, T> {
        let start = row * self.cols;
        RowMut {
            values: &mut self.values[start..start + self.cols],
        }
    }

    pub fn rows(&self) -> std::slice::ChunksExact<'_, T> {
        self.values.chunks_exact(self.cols.max(1))
    }
}

pub struct ArrayView1<'a, T> {
    values: &'a [T],
}

impl<'a, T> ArrayView1<'a, T> {
    pub fn from(values: &'a [T]) -> Self {
        Self { values }
    }
}

pub struct RowMut<'a, T> {
    values: &'a mut [T],
}

impl<T: Clone> RowMut<'_, T> {
    pub fn assign(&mut self, values: &ArrayView1<'_, T>) {
        self.values.clone_from_slice(values.values);
    }

    pub fn fill(&mut self, value: T) {
        self.values.fill(value);
    }
}

impl<T> RowMut<'_, T> {
    pub fn as_slice_mut(&mut self) -> Option<&mut [T]> {
        Some(self.values)
    }
}

impl<T> Index<[usize; 2]> for Array2<T> {
    type Output = T;

    fn index(&self, index: [usize; 2]) -> &Self::Output {
        &self.values[index[0] * self.cols + index[1]]
    }
}

impl<T> IndexMut<[usize; 2]> for Array2<T> {
    fn index_mut(&mut self, index: [usize; 2]) -> &mut Self::Output {
        &mut self.values[index[0] * self.cols + index[1]]
    }
}
"#
        .to_string(),
        tests: "",
    }
}

#[test]
fn corpus_rerun_plan_tracks_every_real_corpus_as_backlog_or_regression_guard() {
    let corpora = fs::read_to_string("docs/corpora.tsv").unwrap();
    let plan = fs::read_to_string("docs/corpus-rerun-idiom-gap-plan.md").unwrap();
    let mut missing = Vec::new();

    for line in corpora.lines().skip(1) {
        let columns: Vec<&str> = line.split('\t').collect();
        if columns.len() < 2 {
            continue;
        }
        let name = columns[0];
        let kind = columns[1];
        if matches!(kind, "snippet" | "synthetic") {
            continue;
        }
        if !plan.contains(&format!("`{name}`")) {
            missing.push(name.to_string());
        }
    }

    assert!(
        missing.is_empty(),
        "real corpuses missing from docs/corpus-rerun-idiom-gap-plan.md: {missing:?}"
    );
}

