#[test]
fn foreach_lambda_throw_wraps_enclosing_method_in_result() {
    let translation = translate_source(
        r#"
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.Future;

class FutureGetForEachCatchThrow {
    Map<String, Reader> run(Map<String, Future<Reader>> futures) {
        Map<String, Reader> readers = new LinkedHashMap<>();
        futures.forEach((name, future) -> {
            try {
                Reader reader = future.get();
                readers.put(name, reader);
            } catch (ExecutionException e) {
                throw new UserException("bad", e);
            }
        });
        return readers;
    }
}

class Reader {
}
"#,
    );

    assert!(
        translation.rust.contains(
            "pub fn run(&self, futures: &std::collections::HashMap<String, Future<Reader>>) -> Result<std::collections::HashMap<String, Reader>, JavaException>"
        ) && translation
            .rust
            .contains("Err(e) if e.is_instance(&[\"ExecutionException\"])")
            && translation.rust.contains("let mut reader: Reader = future.get()?;")
            && translation.rust.contains("return Err(JavaException::with_cause(\"UserException\"")
            && translation.rust.contains("readers.insert(name.clone(), reader);")
            && translation.rust.contains("return Ok((readers).into_iter().collect::<std::collections::HashMap<_, _>>());"),
        "{}",
        translation.rust
    );

    cargo_test_generated_modules(
        "foreach_lambda_throw_wraps_enclosing_method_in_result",
        vec![GeneratedCrateModule {
            name: "fixture",
            rust: translation.rust,
            tests: r#"
#[cfg(test)]
mod generated_tests {
    use super::*;

    #[test]
    fn catches_unmodelled_future_get_and_wraps_cause() {
        let fixture = FutureGetForEachCatchThrow {};
        let mut futures = std::collections::HashMap::new();
        futures.insert("sample".to_string(), Future::<Reader>::default());
        let err = match fixture.run(&futures) {
            Ok(_) => panic!("expected Future.get to raise ExecutionException"),
            Err(err) => err,
        };
        assert_eq!(err.class_name(), "UserException");
        let cause = err.cause().unwrap();
        assert_eq!(cause.class_name(), "ExecutionException");
        assert!(cause.is_instance(&["Exception"]));
    }
}
"#,
        }],
    );
}

