#[test]
fn source_super_constructor_with_trailing_throw_guard_lowers() {
    let subclass = r#"
class CheckedChild extends CheckedBase {
    CheckedChild(String name, int count, String kind) {
        super(name, count, kind, "CHILD");
        if (count < 0)
            throw new IllegalArgumentException("bad count");
    }
}
"#;
    let superclass = r#"
class CheckedBase {
    private final String name;
    private final int count;
    private final String kind;
    private final String target;

    CheckedBase(String name, int count, String kind, String target) {
        this.name = name;
        this.count = count;
        this.kind = kind;
        this.target = target;
    }
}
"#;

    let translation = translate_source_with_context_sources(
        subclass,
        &[superclass.to_string()],
        &FactSet::default(),
    );

    assert!(
        translation.rust.contains("__java_self.name = Some(name)")
            && translation.rust.contains("__java_self.count =")
            && translation.rust.contains("__java_self.kind = Some(kind)")
            && translation
                .rust
                .contains("__java_self.target = Some(\"CHILD\".to_string())")
            && translation
                .rust
                .contains("-> Result<CheckedChild, JavaException>")
            && translation.rust.contains("if count < 0")
            && translation
                .rust
                .contains("return Err(JavaException::new(\"IllegalArgumentException\"")
            && !translation
                .rust
                .contains("super(...) requires inheritance lowering")
            && !translation.rust.contains("compile_error!"),
        "{}",
        translation.rust
    );

    cargo_test_generated_modules(
        "source_super_constructor_with_trailing_throw_guard",
        vec![GeneratedCrateModule {
            name: "fixture",
            rust: translation.rust,
            tests: r#"
#[test]
fn superclass_initialization_precedes_child_guard() {
    let value = CheckedChild::new("name".to_string(), 2, "kind".to_string()).unwrap();
    assert_eq!(value.name.as_deref(), Some("name"));
    assert_eq!(value.count, 2);
    assert_eq!(value.kind.as_deref(), Some("kind"));
    assert_eq!(value.target.as_deref(), Some("CHILD"));
    assert!(CheckedChild::new("name".to_string(), -1, "kind".to_string()).is_err());
}
"#,
        }],
    );
}

