#[test]
fn source_super_constructor_with_child_locals_and_nested_field_assignment_lowers() {
    let subclass = r#"
class ParsedChild extends ParsedBase {
    private String name;
    private String source;

    ParsedChild(String line, boolean modern) {
        super("KEY", "");
        String parsed = line.trim();
        name = parsed;
        if (modern) {
            this.source = parsed;
        }
    }
}
"#;
    let superclass = r#"
class ParsedBase {
    private final String key;
    private final String value;

    ParsedBase(String key, String value) {
        this.key = key;
        this.value = value;
    }
}
"#;

    let translation = translate_source_with_context_sources(
        subclass,
        &[superclass.to_string()],
        &FactSet::default(),
    );

    let parsed_pos = translation.rust.find("let parsed").unwrap_or_else(|| {
        panic!(
            "child constructor local should be emitted:\n{}",
            translation.rust
        )
    });
    let self_pos = translation
        .rust
        .find("let mut __java_self = ParsedChild")
        .unwrap_or_else(|| {
            panic!(
                "child self temporary should be emitted:\n{}",
                translation.rust
            )
        });
    assert!(
        self_pos < parsed_pos
            && translation
                .rust
                .contains("__java_self.key = Some(\"KEY\".to_string())")
            && translation
                .rust
                .contains("__java_self.value = Some(\"\".to_string())")
            && translation
                .rust
                .contains("__java_self.name = Some(std::clone::Clone::clone(&parsed)")
            && translation
                .rust
                .contains("__java_self.source = Some(std::clone::Clone::clone(&parsed)")
            && !translation
                .rust
                .contains("super(...) requires inheritance lowering")
            && !translation.rust.contains("compile_error!"),
        "{}",
        translation.rust
    );

    cargo_test_generated_modules(
        "source_super_constructor_with_child_locals",
        vec![GeneratedCrateModule {
            name: "fixture",
            rust: translation.rust,
            tests: r#"
#[test]
fn child_locals_and_conditional_stores_follow_superclass_initialization() {
    let modern = ParsedChild::new(" value ", true);
    assert_eq!(modern.key.as_deref(), Some("KEY"));
    assert_eq!(modern.value.as_deref(), Some(""));
    assert_eq!(modern.name.as_deref(), Some("value"));
    assert_eq!(modern.source.as_deref(), Some("value"));
    let legacy = ParsedChild::new(" legacy ", false);
    assert_eq!(legacy.name.as_deref(), Some("legacy"));
    assert_eq!(legacy.source, None);
}
"#,
        }],
    );
}

