#[test]
/// A self-referential field is stored behind a shared handle, not a `Box`.
///
/// `Option<Box<T>>` gives each node *exclusive* ownership of its parent, which
/// no Java object graph has. The `Box` existed only to break the recursion, and
/// the handle breaks it too. See claude_audits/0002.
fn source_self_referential_instance_fields_use_shared_handle_storage() {
    let translation = translate_source(
        r#"
class SelfLinkedNode {
    private SelfLinkedNode parent;
    private SelfLinkedNode child;
}
"#,
    );

    assert!(
        translation
            .rust
            .contains("parent: Option<std::rc::Rc<SelfLinkedNode>>")
            && translation
                .rust
                .contains("child: Option<std::rc::Rc<SelfLinkedNode>>")
            && !translation.rust.contains("Option<Box<SelfLinkedNode>>")
            && !translation.rust.contains("parent: Option<SelfLinkedNode>")
            && !translation.rust.contains("child: Option<SelfLinkedNode>"),
        "{}",
        translation.rust
    );

    cargo_check_generated_modules(
        "source_self_referential_instance_fields_use_shared_handle",
        vec![GeneratedCrateModule {
            name: "fixture",
            rust: translation.rust,
            tests: "",
        }],
    );
}

#[test]
fn jdk_stream_wrapper_super_with_self_linking_trailing_mutation_is_precise_gap() {
    let translation = translate_source(
        r#"
import java.io.InputStream;
import java.util.zip.GZIPInputStream;

class ParentLinkedGzipStream extends GZIPInputStream {
    private ParentLinkedGzipStream parent;
    private ParentLinkedGzipStream child;
    private int size;

    ParentLinkedGzipStream(InputStream input) {
        super(input);
        this.size = -1;
    }

    private ParentLinkedGzipStream(ParentLinkedGzipStream parent) {
        super(parent.in);
        this.size = -1;
        this.parent = parent.parent == null ? parent : parent.parent;
        this.parent.child = this;
    }

    ParentLinkedGzipStream next() {
        return new ParentLinkedGzipStream(this);
    }
}
"#,
    );

    assert!(
        translation.rust.contains(
            "unsupported Java constructor: super(...) followed by unsupported object graph mutation"
        ) && !translation
            .rust
            .contains("unsupported Java constructor: super(...) requires inheritance lowering")
            && translation
                .rust
            .contains("panic!(\"unsupported Java constructor: super(...) followed by unsupported object graph mutation\")"),
        "{}",
        translation.rust
    );

    cargo_check_generated_modules_fails_with(
        "jdk_stream_wrapper_super_self_linking_trailing_mutation_gap",
        vec![GeneratedCrateModule {
            name: "fixture",
            rust: translation.rust,
            tests: "",
        }],
        "unsupported Java constructor: super(...) followed by unsupported object graph mutation",
    );
}

