#[test]
/// A singleton getter hands back a shared handle, not a value.
///
/// Returning `Config` by value gave every caller its own copy, so the singleton
/// was not one. `Arc` rather than `Rc` because the value is reachable from a
/// Java `static`, which is shared across threads and so must be `Sync`.
fn private_static_singleton_getter_lowers_to_shared_handle() {
    let translation = translate_source(
        r#"
class StaticSingletonGetterUse {
    boolean enabled() {
        return Config.getInstance().svgOutput;
    }
}

class Config {
    private static Config instance = new Config();
    public boolean svgOutput = true;

    private Config() {
        svgOutput = true;
    }

    public static Config getInstance() {
        return instance;
    }
}
"#,
    );

    assert!(
        translation
            .rust
            .contains("pub fn get_instance() -> std::sync::Arc<Config>")
            && translation
                .rust
                .contains("get_or_insert_with(|| std::sync::Arc::new(Config::new()))")
            && translation
                .rust
                .contains("return Config::get_instance().svg_output;")
            && !translation.rust.contains("return Some(&instance);")
            && !translation.rust.contains("Option<&Config>"),
        "{}",
        translation.rust
    );

    cargo_check_generated_modules(
        "private_static_singleton_getter",
        vec![GeneratedCrateModule {
            name: "fixture",
            rust: translation.rust,
            tests: "",
        }],
    );
}

#[test]
fn private_static_singleton_with_hashmap_field_derives_clone_when_value_is_cloneable() {
    let translation = translate_source(
        r#"
import java.util.HashMap;

class StaticSingletonHashMapGetterUse {
    Format get(String id) {
        return Factory.getInstance().getFormat(id);
    }
}

class Factory {
    private static Factory instance = null;
    private HashMap<String, Format> formats = new HashMap<String, Format>();

    static Factory getInstance() {
        if (instance == null) {
            instance = new Factory();
        }
        return instance;
    }

    Format getFormat(String id) {
        return (Format) formats.get(id);
    }
}

class Format {}
"#,
    );

    assert!(
        translation.rust.contains("#[derive(Clone")
            && translation.rust.contains(
                // `Arc`, not `Rc`: `Format` is reachable from a Java `static`, so
                // its handle must be `Sync` (claude_audits/0002b).
                "pub struct Factory {\n    formats: std::collections::HashMap<String, std::sync::Arc<Format>>"
            )
            && translation.rust.contains("pub fn get_instance() -> Option<Factory>")
            && translation.rust.contains("return Factory::get_instance().as_ref().unwrap().get_format(&id).unwrap();")
            // See claude_audits/0030: static storage is a process-wide `Mutex`.
            && translation
                .rust
                .contains("static FACTORY_INSTANCE: std::sync::Mutex<Option<Option<Factory>>>")
            && !translation.rust.contains("downcast::<Format>")
            && !translation.rust.contains("invalid Java cast"),
        "{}",
        translation.rust
    );

    cargo_check_generated_modules(
        "private_static_singleton_hashmap_getter",
        vec![GeneratedCrateModule {
            name: "fixture",
            rust: translation.rust,
            tests: "",
        }],
    );
}

