#[test]
fn two_dimensional_numeric_arrays_lower_to_ndarray_array2() {
    let translation = translate_source(
        r#"
class NdarrayMatrixLowering {
    double[][] literal() {
        return new double[][] {{1.0, 2.0}, {3.0, 4.0}};
    }

    double[][] create(int rows, int cols) {
        double[][] values = new double[rows][cols];
        values[0][0] = 1.0;
        return values;
    }

    double read(double[][] values, int row, int col) {
        return values[row][col];
    }

    void write(double[][] values, int row, int col, double value) {
        values[row][col] = value;
    }

    void writeParsed(float[][] scores, int row, int col, String value) {
        scores[row][col] = Float.parseFloat(value);
    }

    float[][] createAndWriteParsed(int rows, int cols, int row, int col, String value) {
        float[][] scores = new float[rows][cols];
        scores[row][col] = Float.parseFloat(value);
        return scores;
    }

    float[][] createAndWriteParsedToken(int rows, int cols, int row, int col, java.util.StringTokenizer tokenizer) {
        float[][] scores = new float[rows][cols];
        scores[row][col] = Float.parseFloat(tokenizer.nextToken());
        return scores;
    }

    int rows(double[][] values) {
        return values.length;
    }

    int cols(double[][] values, int row) {
        return values[row].length;
    }
}
"#,
    );

    assert!(
        translation
            .rust
            .contains("pub fn literal(&self) -> ndarray::Array2<f64>"),
        "{}",
        translation.rust
    );
    assert!(
        translation
            .rust
            .contains("return ndarray::arr2(&[[1f64, 2f64], [3f64, 4f64]]);"),
        "{}",
        translation.rust
    );
    assert!(
        translation.rust.contains(
            "let mut values: ndarray::Array2<f64> = ndarray::Array2::from_elem((rows as usize, cols as usize), 0.0);"
        ),
        "{}",
        translation.rust
    );
    assert!(
        translation.rust.contains("let __java_arrays_row = row;"),
        "{}",
        translation.rust
    );
    assert!(
        translation
            .rust
            .contains("values: &mut ndarray::Array2<f64>"),
        "{}",
        translation.rust
    );
    assert!(
        translation
            .rust
            .contains("values[[row as usize, col as usize]] = value;"),
        "{}",
        translation.rust
    );
    assert!(
        translation
            .rust
            .contains("scores[[row as usize, col as usize]] = java_float_parse_f32(&value).map_err(|err| JavaException::from_display(\"NumberFormatException\", err))?;")
            && !translation.rust.contains(
                "scores[[row as usize, col as usize]] = &value.as_str().parse::<f32>().unwrap();"
            ),
        "{}",
        translation.rust
    );
    assert!(
        translation
            .rust
            .contains("let mut scores: ndarray::Array2<f32> = ndarray::Array2::from_elem((rows as usize, cols as usize), 0.0);")
            && !translation.rust.contains("scores[[row as usize, col as usize]] = &value.as_str().parse::<f32>()"),
        "{}",
        translation.rust
    );
    assert!(
        translation
            .rust
            .contains("scores[[row as usize, col as usize]] = java_float_parse_f32(&tokenizer.next_token_result()?).map_err(|err| JavaException::from_display(\"NumberFormatException\", err))?;")
            && !translation.rust.contains("scores[[row as usize, col as usize]] = &tokenizer.next_token().parse::<f32>()"),
        "{}",
        translation.rust
    );
    assert!(
        translation
            .rust
            .contains("return Ok(values.nrows() as i32);"),
        "{}",
        translation.rust
    );
    assert!(
        translation.rust.contains(
            "return Ok({ let __java_arrays_source = &values; let __java_arrays_row = row;"
        ),
        "{}",
        translation.rust
    );
    assert!(
        !translation.rust.contains("Vec<Vec<f64>>"),
        "{}",
        translation.rust
    );
    assert!(
        !translation
            .rust
            .contains("Java array creation: Primitive(Double)"),
        "{}",
        translation.rust
    );

    cargo_check_generated_modules(
        "two_dimensional_numeric_arrays_ndarray_array2",
        vec![
            ndarray_stub_module(),
            GeneratedCrateModule {
                name: "fixture",
                rust: format!("use crate::ndarray;\n{}", translation.rust),
                tests: "",
            },
        ],
    );
}

